package network.conet.chat.nativekey

import network.conet.chat.ConetChatCryptoUtil
import org.json.JSONArray
import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File
import java.security.MessageDigest

/**
 * Native OpenPGP (nativekey/NativePgp.kt) against two independent sources:
 *  - `spec/pgp-native-vectors.v1.json`: keys, messages and signatures from openpgp.js 6.3.0 (the library the app ships),
 *    generated by `scripts/gen-pgp-native-vectors.mjs`. Includes passphrase-protected ECC and RSA keys.
 *  - the chat-daemon envelope vectors (`spec/chat-daemon-vectors.v1.json`, classpath resource): PGP messages from the
 *    protocol owner, checked by armor hash, literal structure and the expected JSON.
 * Only synthetic material is used. The old WebView decryption is no longer part of the build.
 */
class NativePgpInteropTest {
    private val bytes = File(System.getenv("PGP_NATIVE_VECTORS") ?: "../spec/pgp-native-vectors.v1.json").readBytes()
    private val v = JSONObject(String(bytes, Charsets.UTF_8))

    private fun sha256Hex(b: ByteArray): String =
        MessageDigest.getInstance("SHA-256").digest(b).joinToString("") { "%02x".format(it) }

    private fun secretOf(keyId: String): NativePgp.Secret {
        val k = v.getJSONObject("keys").getJSONObject(keyId)
        return NativePgp.parseSecret(k.getString("privateArmored")) ?: error("key $keyId did not parse")
    }

    @Test
    fun vectorFileIsTheCanonicalOne() {
        assertEquals("d385b33f68767b98afdb4e061fbb1cf31ecf2d394345a1182f70ab064c181439", sha256Hex(bytes))
    }

    @Test
    fun keysParseWithTheExpectedFingerprints() {
        val keys = v.getJSONObject("keys")
        for (id in keys.keys()) {
            val k = keys.getJSONObject(id)
            assertEquals("$id fingerprint", k.getString("fingerprint"), secretOf(id).fingerprint)
        }
    }

    @Test
    fun everyDecryptionCaseMatchesOpenPgpJs() {
        val cases = v.getJSONArray("decrypt")
        assertEquals(9, cases.length())
        for (i in 0 until cases.length()) {
            val c = cases.getJSONObject(i)
            val id = c.getString("id")
            val expect = c.getJSONObject("expect")
            val out = NativePgp.decryptMessage(secretOf(c.getString("key")), c.getString("passphrase"), c.getString("armor"))
            if (expect.has("code")) {
                assertEquals("$id code", expect.getString("code"), out.code)
            }
            if (expect.has("codeIn")) {
                val allowed = expect.getJSONArray("codeIn")
                assertTrue("$id code ${out.code} not in $allowed", (0 until allowed.length()).any { allowed.getString(it) == out.code })
            }
            if (expect.has("text")) {
                assertTrue("$id ok", out.ok)
                assertEquals("$id text", expect.getString("text"), out.value)
            }
        }
    }

    @Test
    fun everyDocumentSignatureCaseMatchesOpenPgpJs() {
        val cases = v.getJSONArray("signatures")
        assertEquals(3, cases.length())
        for (i in 0 until cases.length()) {
            val c = cases.getJSONObject(i)
            val id = c.getString("id")
            val label = "beamio.pgp.${c.getString("purpose")}.v1\n"
            val verified = NativePgp.verifyDocument(
                secretOf(c.getString("key")),
                label,
                c.getString("message").toByteArray(Charsets.UTF_8),
                c.getString("armoredSignature"),
            )
            assertEquals("$id verify", c.getJSONObject("expect").getBoolean("verify"), verified)
        }
    }

    @Test
    fun chatDaemonEnvelopesDecryptWithTheirExpectedStructure() {
        val stream = javaClass.classLoader!!.getResourceAsStream("chat-daemon-vectors.v1.json")
            ?: error("chat-daemon-vectors.v1.json missing from test resources")
        val vectors = JSONObject(stream.bufferedReader(Charsets.UTF_8).readText())
        val keys = vectors.getJSONObject("keys")
        val envelopes: JSONArray = vectors.getJSONArray("envelopes")
        assertEquals(3, envelopes.length())
        for (i in 0 until envelopes.length()) {
            val c = envelopes.getJSONObject(i)
            val name = c.getString("name")
            val secret = NativePgp.parseSecret(keys.getJSONObject(c.getString("decryptWith")).getString("privateArmored"))
            assertNotNull("$name key", secret)
            val armor = c.getString("armor")
            val out = NativePgp.decryptMessage(secret!!, "", armor)
            assertTrue("$name decrypt ${out.code}", out.ok)
            assertEquals("$name armorHash", c.getString("armorHash"), NativePgp.armorHash(armor))
            val text = out.value!!
            val obj = if (c.getString("literal") == "base64-json") {
                JSONObject(String(ConetChatCryptoUtil.base64Decode(text), Charsets.UTF_8))
            } else {
                JSONObject(text)
            }
            assertTrue("$name structure", jsonEquals(obj, c.getJSONObject("expect")))
            c.optJSONObject("messageJson")?.let {
                assertTrue("$name message", jsonEquals(JSONObject(obj.getString("message")), it))
            }
        }
    }

    private fun jsonEquals(a: Any?, b: Any?): Boolean = when {
        a is JSONObject && b is JSONObject -> {
            val ka = a.keys().asSequence().toSet()
            val kb = b.keys().asSequence().toSet()
            ka == kb && ka.all { jsonEquals(a.opt(it), b.opt(it)) }
        }
        a is JSONArray && b is JSONArray ->
            a.length() == b.length() && (0 until a.length()).all { jsonEquals(a.opt(it), b.opt(it)) }
        a is Number && b is Number -> a.toDouble() == b.toDouble() && a.toLong() == b.toLong()
        else -> a == b
    }
}
